import{_ as e,o as c,a as i,b as s}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"asc_sync_intra_wait","link":"/api/SIMD-API/c_api/sync/asc_sync_intra_wait"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/asc_sync_intra_wait.md","filePath":"api/SIMD-API/c_api/sync/asc_sync_intra_wait.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788779718000}'),d={name:"api/SIMD-API/c_api/sync/asc_sync_intra_wait.md"};function t(l,a,n,o,_,r){return c(),i("div",null,[...a[0]||(a[0]=[s(`<div><article class="markdown-body"><h1>asc_sync_intra_wait</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/sync/sync.h&quot;</code>。</p><p>本接口与<a href="asc_sync_intra_arrive.html">asc_sync_intra_arrive</a>配对使用，实现单AI Core内AIC与单个AIV之间的同步（<a href="system_sync_overview.html#fig_sync_control_mode">四种核间同步模式</a>中的模式4），核间同步实现的原理如下：</p><ul><li>单个AIV等待AIC的场景： <ul><li>单AI Core内AIC执行<code>asc_sync_intra_arrive</code>后向调度模块发送通知，接着调度模块将该AI Core内单个AIV对应<code>sync_id</code>的计数器增加1。</li><li>单个AIV上配对的<code>asc_sync_intra_wait</code>检测到对应<code>sync_id</code>的计数器非0后解除阻塞并将计数器减1。</li></ul></li><li>AIC等待单个AIV的场景： <ul><li>单AI Core内单个AIV执行<code>asc_sync_intra_arrive</code>后向调度模块发送通知，接着调度模块将AIC对应<code>sync_id</code>的计数器增加1。</li><li>AIC上配对的<code>asc_sync_intra_wait</code>检测到对应<code>sync_id</code>的计数器非0后解除阻塞并将计数器减1。</li></ul></li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_sync_intra_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span>
<span class="w">                                           </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">sync_id</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">pipe</td><td align="left">输入</td><td align="left">标识阻塞哪条流水的后续指令，直到对应<code>sync_id</code>的计数器非0。<br>参数的类型是<code>pipe_t</code>枚举，各个枚举取值的含义请参考<a href="./intra_core_sync_overview.html#%E7%A1%AC%E4%BB%B6%E6%B5%81%E6%B0%B4%E7%B1%BB%E5%9E%8B">硬件流水类型</a>。<br>AIC和AIV支持的<code>pipe</code>取值请参考<a href="#supported_pipe_combinations">约束说明</a>。</td></tr><tr><td align="left">sync_id</td><td align="left">输入</td><td align="left">核间同步的标记，用于标识同一组同步信号。每个<code>sync_id</code>各自拥有独立的4位计数器。一个AI Core由1个AIC与2个AIV构成，AIC侧拥有32个<code>sync_id</code>（0~31），每个AIV侧各拥有16个<code>sync_id</code>（0~15）。<br>同步时<code>asc_sync_intra_arrive</code>与<code>asc_sync_intra_wait</code>的<code>sync_id</code>对应关系请参考<a href="#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">约束说明</a>。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>针对<code>asc_sync_intra_arrive</code>接口，传入的<code>pipe</code>参数<strong>生效</strong>，AIC和AIV支持的<code>pipe</code>取值如<a href="#aic_aiv_supported_pipe">表2</a>所示。<a id="supported_pipe_combinations"></a></p><p><strong>表2</strong> AIC和AIV支持的<code>pipe</code>取值<a id="aic_aiv_supported_pipe"></a></p><table><thead><tr><th align="left">核类型</th><th align="left">支持的pipe取值</th></tr></thead><tbody><tr><td align="left">AIC</td><td align="left"><code>PIPE_S</code>、<code>PIPE_M</code>、<code>PIPE_MTE1</code>、<code>PIPE_MTE2</code>、<code>PIPE_FIX</code></td></tr><tr><td align="left">AIV</td><td align="left"><code>PIPE_S</code>、<code>PIPE_MTE2</code>、<code>PIPE_MTE3</code>、<code>PIPE_V</code></td></tr></tbody></table></li><li><p>调用本接口的核函数必须使用<code>__mix__(1, 2)</code>修饰。</p></li><li><p>与其它核间同步模式不同，本接口与<code>asc_sync_intra_arrive</code>配对使用时，<strong>不要求</strong><code>arrive</code>与<code>wait</code>传入的<code>sync_id</code>相同，而是要求二者符合如下跨核ID映射关系，否则会出现未定义行为。<a id="sync_id_mapping"></a></p><ul><li>AIV0中调用的<code>asc_sync_intra_arrive</code>接口的<code>sync_id</code>取值为0~15，分别与AIC中调用的<code>asc_sync_intra_wait</code>接口的<code>sync_id</code>取值0~15对应。</li><li>AIV1中调用的<code>asc_sync_intra_arrive</code>接口的<code>sync_id</code>取值为0~15，分别与AIC中调用的<code>asc_sync_intra_wait</code>接口的<code>sync_id</code>取值16~31对应。</li><li>AIC中调用的<code>asc_sync_intra_arrive</code>接口的<code>sync_id</code>取值为0~15，分别与AIV0中调用的<code>asc_sync_intra_wait</code>接口的<code>sync_id</code>取值0~15对应。</li><li>AIC中调用的<code>asc_sync_intra_arrive</code>接口的<code>sync_id</code>取值为16~31，分别与AIV1中调用的<code>asc_sync_intra_wait</code>接口的<code>sync_id</code>取值0~15对应。</li></ul></li><li><p>每个计数器最多连续累加15次（此时计数器的值为15），必须保证计数器的值不超过15，否则触发异常。</p></li><li><p>本接口会阻塞<code>pipe</code>流水中的后续指令；对应<code>sync_id</code>的计数器非0时解除阻塞，并将计数器减1。</p></li><li><p>AIC的<code>sync_id</code>取值范围为[0, 31]，超出范围值会被按位宽截断处理为低5位（例如，syncId=32时，截取后为0；syncId=33时，截取后为1）。</p></li><li><p>AIV的<code>sync_id</code>取值范围为[0, 15]，超出范围值会被按位宽截断处理为低4位（例如，syncId=16时，截取后为0；syncId=17时，截取后为1）。</p></li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p><code>asc_sync_intra_wait</code>需与<code>asc_sync_intra_arrive</code>配对使用，具体调用示例请参考<a href="asc_sync_intra_arrive.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">asc_sync_intra_arrive调用示例</a>。</p></article></div>`,1)])])}const A=e(d,[["render",t]]);export{h as __pageData,A as default};
